// Feed this node a payload with one object per insight key.
// Each object should contain state, explanation, severity, confidence, and optionally icon.
// Example: msg.payload.rain_outlook = { state: 'Rain likely soon', explanation: '82% likelihood in 60 minutes', severity: 'rain', confidence: 88 }
const input = msg.payload || {};
const device = { identifiers: ['weather_station_core'], name: 'Weather Station Core', manufacturer: 'Weather Station Core', model: 'Interpreted insights', sw_version: '0.4.0' };
const base = 'weather_station_core/insights/';
const insights = {
  heating_demand: { name: 'Heating demand', icon: 'mdi:home-thermometer' },
  rain_outlook: { name: 'Rain outlook', icon: 'mdi:weather-rainy' },
  data_confidence: { name: 'Data confidence', icon: 'mdi:check-decagram' },
  comfort: { name: 'Comfort and condensation', icon: 'mdi:water-percent' },
  frost_risk: { name: 'Frost risk', icon: 'mdi:snowflake-alert' },
  wind_chill: { name: 'Wind chill exposure', icon: 'mdi:weather-windy' },
  drying_window: { name: 'Drying window', icon: 'mdi:weather-sunny' }
};
const messages = [];
Object.entries(insights).forEach(([key, definition]) => {
  const value = input[key] || {};
  const stateTopic = `${base}${key}/state`;
  const configTopic = `homeassistant/sensor/weather_station_core_${key}/config`;
  messages.push({ topic: configTopic, retain: true, payload: JSON.stringify({ name: definition.name, unique_id: `weather_station_core_${key}`, object_id: `weather_station_core_${key}`, state_topic: stateTopic, value_template: '{{ value_json.state }}', json_attributes_topic: stateTopic, icon: value.icon || definition.icon, device }) });
  messages.push({ topic: stateTopic, retain: true, payload: JSON.stringify({ state: value.state ?? 'Unavailable', explanation: value.explanation ?? '', severity: value.severity ?? 'normal', confidence: value.confidence ?? null, icon: value.icon || definition.icon, updated_at: new Date().toISOString() }) });
});
return [messages];
